() => {
  const overlays = document.querySelectorAll('.html2pdf__overlay, .html2pdf__container');
  const modal = !!document.querySelector('[class*="fixed"][class*="inset-0"]');
  const successToast = document.body.innerText.includes('高清 PDF 导出成功');
  const exportBtn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('导出高清 PDF'));
  return {
    residualOverlays: overlays.length,
    anyFixedOverlay: modal,
    successToastVisible: successToast,
    exportBtnDisabled: exportBtn ? exportBtn.disabled : null,
    scrollY: window.scrollY
  };
}

async () => {
